// Two variable definitions

const initial_conc = [0.200, 0.225, 0.250, 0.275, 0.300, 0.325, 0.350, 0.375, 0.400, 0.425, 0.450, 0.475, 0.500];

const count = OLI.random(0,12);
const conc = initial_conc[count] .toPrecision(3);

const d = OLI.random(1,9.99,1) .toPrecision(2);
const e = OLI.random(-8, -4,0);
const ka = d*10**e .toPrecision(2);

var h = 0;
for (let step = 0; step < 10; step++) {
  h = Math.sqrt(ka*(conc - h));
}

const hsf = h .toPrecision(2);
const oh = 0.00000000000001/h;
const ohsf = oh .toPrecision(2);
const ph = -Math.log10(h);
const phsf = ph .toPrecision(3);
const hsflow = 0.98*hsf;
const hsfhigh = 1.02*hsf;
const phlow = 0.98*phsf;
const phhigh = 1.02*phsf;
const ohsflow = 0.98*ohsf;
const ohsfhigh = 1.02*ohsf;

// Expose variables to OLI
module.exports = {
  conc, d, e, ka, h, hsf, hsflow, hsfhigh, oh, ohsf, ohsflow, ohsfhigh, ph, phsf, phlow, phhigh
};
